text:
{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Bureaucracy of the Afterlife",
          "intent": "Establish Rhea's death and her immediate, disorienting arrival in the Ledger's frontier tutorial zone, highlighting the hostile UI.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea successfully parses her first System notification and avoids immediate environmental death."
        },
        {
          "section_id": 2,
          "title": "The Starter Pack Trap",
          "intent": "Reveal that the tutorial's 'helpful' starter gear is actually a predatory debt trap designed to enslave new arrivals.",
          "section_role": "complication",
          "target_scene_count": 2,
          "end_condition": "Rhea identifies the hidden interest rate on the starter gear and explicitly refuses the standard acceptance prompt."
        },
        {
          "section_id": 3,
          "title": "Exploiting the Fine Print",
          "intent": "Rhea finds a loophole in the System's wording to secure basic gear without triggering the debt mechanics.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Rhea equips her first exploited item and receives a non-standard System confirmation of survival."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Cost of Breathing",
          "intent": "Rhea attempts to gather basic resources but encounters the local tariff mechanics that drain stamina and HP.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea hits critical stamina levels and realizes standard gathering will bankrupt her HP before nightfall."
        },
        {
          "section_id": 2,
          "title": "Physics vs. The System",
          "intent": "Rhea observes local mob behavior and loot drop rules, spotting a discrepancy between physics and System taxation.",
          "section_role": "action",
          "target_scene_count": 2,
          "end_condition": "Rhea successfully forces a mob to drop untaxed raw materials by exploiting a collision between environmental damage and loot generation."
        },
        {
          "section_id": 3,
          "title": "Establishing a Baseline",
          "intent": "Rhea converts the untaxed materials into usable sustenance and currency, securing her immediate survival.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Rhea secures a positive daily resource yield and banks her first untaxed copper credits."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Unwanted Attention",
          "intent": "Rhea's economic exploit draws the attention of a desperate fellow arrival and a cynical, low-level system clerk.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea is cornered by the clerk and the arrival, forcing a tense negotiation over her exploit methodology."
        },
        {
          "section_id": 2,
          "title": "A Test of Synergy",
          "intent": "The trio tests a joint venture, combining Rhea's exploit with the arrival's combat skill and the clerk's limited system access.",
          "section_role": "action",
          "target_scene_count": 2,
          "end_condition": "The newly formed party successfully completes a rigged local quest with zero net loss to their resources."
        },
        {
          "section_id": 3,
          "title": "The Liability Contract",
          "intent": "Formalize the party alliance using Rhea's strict, loophole-free legal wording to prevent future betrayal.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The System registers the party under a custom, highly restrictive liability contract."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "Mathematical Discrepancies",
          "intent": "As the party grinds quests, Rhea notices the math on XP and loot yields doesn't match the System's stated formulas.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea compiles a ledger of missing XP and loot, proving a mathematical discrepancy in the local node."
        },
        {
          "section_id": 2,
          "title": "Tracking the Leak",
          "intent": "The party investigates the missing value, tracking it through the local frontier node's routing system.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "The party discovers the digital skim point where the local administrator is routing the stolen rewards."
        },
        {
          "section_id": 3,
          "title": "Securing the Evidence",
          "intent": "Rhea secures hard evidence of the administrative fraud before the system can wipe the logs.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Rhea locks the proof of the skim into her personal, unalterable System inventory."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Filing the Grievance",
          "intent": "Rhea drafts and submits a metaphysical grievance using the Ledger's own obscure audit rules.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea successfully submits the grievance, triggering an automated System freeze on the local node's assets."
        },
        {
          "section_id": 2,
          "title": "The Violent Refund",
          "intent": "The System processes the audit, violently refunding the stolen XP and loot to the party in the middle of a hostile zone.",
          "section_role": "action",
          "target_scene_count": 3,
          "end_condition": "The party survives the chaotic influx of refunded power and levels up significantly."
        },
        {
          "section_id": 3,
          "title": "The Overseer's Gaze",
          "intent": "The local overseer realizes what happened and manually overrides the automated system to target Rhea.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The party receives a red-tier 'Audit Compliance' warning directly from the overseer."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Weaponized Bureaucracy",
          "intent": "The overseer weaponizes the environment, spawning debt-collecting mobs and applying severe administrative debuffs.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "The party barely escapes the first wave of rigged encounters, their resources heavily drained."
        },
        {
          "section_id": 2,
          "title": "Targeting the Ledger",
          "intent": "Rhea realizes they cannot out-fight the system's infinite resources and must attack the overseer's mana/debt ledger directly.",
          "section_role": "action",
          "target_scene_count": 2,
          "end_condition": "Rhea identifies the specific administrative hub powering the overseer's targeted harassment."
        },
        {
          "section_id": 3,
          "title": "Preparing the Counter-Audit",
          "intent": "The party prepares a counter-audit, gathering the specific items and exploits needed to crash the local node.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The party stands at the threshold of the administrative sanctum, fully equipped for the breach."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "Breaching the Sanctum",
          "intent": "The party fights through the overseer's elite bureaucratic guards and trap-laden architecture.",
          "section_role": "action",
          "target_scene_count": 3,
          "end_condition": "The party breaches the inner office, confronting the overseer directly."
        },
        {
          "section_id": 2,
          "title": "The Default",
          "intent": "The overseer tries to enforce a lethal predatory contract, but Rhea turns the wording against him using her gathered proof.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Rhea triggers a catastrophic default on the overseer's contract, stripping his administrative shields."
        },
        {
          "section_id": 3,
          "title": "System Crash",
          "intent": "The party defeats the vulnerable overseer, causing the local frontier node to crash.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The overseer is deleted, and the System broadcasts a critical failure across the frontier zone."
        }
      ]
    },
    {
      "chapter_id": 8,
      "sections": [
        {
          "section_id": 1,
          "title": "Looting the Cache",
          "intent": "The party loots the collapsing sanctum, securing the 'Mercy Cache' and high-tier administrative residue.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea secures the administrative residue in her inventory, gaining a permanent, illicit system access token."
        },
        {
          "section_id": 2,
          "title": "Outrunning the Purge",
          "intent": "The frontier zone begins to purge and reset, forcing the party to flee toward the civic layer boundary.",
          "section_role": "action",
          "target_scene_count": 2,
          "end_condition": "The party successfully crosses the boundary out of the frontier zone just as it collapses behind them."
        },
        {
          "section_id": 3,
          "title": "The Civic Layer",
          "intent": "Rhea and her party look toward the vast, institutional city, ready to scale their exploits.",
          "section_role": "resolution",
          "target_scene_count": 1,
          "end_condition": "Rhea receives a new, high-stakes System prompt welcoming her to the civic layer, setting up Book 2."
        }
      ]
    }
  ]
}
